package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Action
import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object PropertyCards {
    private val T = Track.PROPERTY
    val cards: List<Card> = listOf(
        // ---------- Level 1: Rookie ----------
        concept("ho-rent-vs-buy", T, 1, "Is renting just \"throwing money away\"?",
            "No. Rent buys a home plus flexibility: you can move for a better job and someone else fixes the roof. Owners pay too, through interest, repairs, rates and the return their deposit could have earned elsewhere. Which is cheaper depends on the numbers.",
            source = "Morph Academy"),
        quiz("ho-title-deed", T, 1, "What document proves who legally owns a piece of land in Kenya?",
            listOf("The title deed (or certificate of lease)", "A sale agreement", "A land rates receipt", "A chief's letter"), 0,
            "The register at the Lands Registry, shown on the title deed or certificate of lease, is the proof. A sale agreement is only a promise until the transfer is registered.",
            source = "Land Registration Act 2012"),
        quiz("ho-official-search", T, 1, "Before paying for a plot, what's the first check to run?",
            listOf("An official search at the Lands Registry", "Ask the neighbours", "Visit on a sunny day", "Ask the seller for an ID copy"), 0,
            "An official search shows the registered owner and any charges, cautions or restrictions on the title. Many counties now do this online through Ardhisasa.",
            source = "Ministry of Lands; Ardhisasa", tryThis = "Look up ardhisasa.lands.go.ke and see if your county is on it."),
        concept("ho-freehold-leasehold", T, 1, "What's the difference between freehold and leasehold land?",
            "Freehold is yours with no end date. Leasehold is yours for a set term (often 99 years in towns) and you pay annual ground rent to the government or county. Check how many years are left on a lease before buying.",
            source = "Land Act 2012"),
        quiz("ho-car-asset", T, 1, "Is a private car you drive to work usually an asset that grows your wealth?",
            listOf("No: it loses value and costs money", "Yes: it always gains value", "Yes, if it's imported", "Only if it's new"), 0,
            "A car usually loses value every year and costs fuel, insurance, parking and service. It can be worth it for time and safety, but treat it as a cost, unless it earns (like a taxi or matatu).",
            source = "Morph Academy"),
        quiz("ho-survey-map", T, 1, "Why look at the survey map (RIM or deed plan) before buying land?",
            listOf("To confirm the plot's size and location", "To find the cheapest seller", "To avoid paying stamp duty", "To skip the land search"), 0,
            "The map shows exactly where the plot sits and its boundaries. Walk the plot with a licensed surveyor to check the beacons match the map.",
            source = "Survey of Kenya"),
        concept("ho-lcb", T, 1, "What is the Land Control Board, and when do you need it?",
            "A local board that must approve most deals in agricultural land: sales, leases, charges and subdivisions. Without its consent, the deal is void. It aims to protect families from losing farmland unfairly.",
            source = "Land Control Act, Cap 302"),
        quiz("ho-deposit-meaning", T, 1, "When buying a home with a mortgage, what is the deposit?",
            listOf("The part of the price you pay upfront", "The monthly repayment", "The bank's fee", "The lawyer's fee"), 0,
            "The deposit is your own money; the bank lends the rest. A bigger deposit means a smaller loan, less interest and less risk.",
            source = "Morph Academy"),
        concept("ho-hidden-costs-own", T, 1, "Beyond the price, what does owning a home cost each year?",
            "Land rates to the county, repairs, insurance, service charge in apartments, ground rent on leasehold, and security. Budget for these before you buy.",
            source = "Morph Academy"),
        quiz("ho-mortgage-def", T, 1, "What is a mortgage?",
            listOf("A loan secured on the property you buy", "A government grant for housing", "A rent-to-own deal", "A land rates payment"), 0,
            "The bank holds a charge over the home. If you stop paying, the lender can sell it to recover the loan. That's why you shouldn't borrow to the limit.",
            source = "Land Act 2012"),
        concept("ho-ardhisasa", T, 1, "What is Ardhisasa?",
            "The Ministry of Lands' online platform for searches, transfers and payments, which aims to cut paperwork and fraud at land registries. Nairobi was among the first counties fully on it.",
            source = "Ministry of Lands"),
        you("ho-you-emergency-first", T, 1, "You're dreaming of a plot. Your emergency target is {emergency_target} and you have {savings} saved. Which comes first?",
            "The emergency fund. Land can't be sold quickly in a crisis, and a plot bought with your safety net leaves you open to Fuliza and shylocks. Hit {emergency_target} first, then save for land separately.",
            tryThis = "Set up a separate pot for land savings.", action = Action.AUTOSORT,
            signals = setOf(Signal.NO_EMERGENCY_FUND)),

        // ---------- Level 2: Hustler ----------
        quiz("ho-buy-steps", T, 2, "What's the right order for buying land in Kenya?",
            listOf("Search, visit with surveyor, agreement, consent, transfer", "Pay, then search", "Transfer, then search", "Agreement, pay in full, then visit"), 0,
            "Check the title first, confirm the plot on the ground, sign a lawyer-drafted agreement, get any needed consents, pay stamp duty and register the transfer. Pay the balance only when the transfer is ready.",
            source = "Ministry of Lands; Land Registration Act 2012"),
        quiz("ho-stamp-duty-urban", T, 2, "You buy a Ksh 4 million plot inside a municipality. What's the stamp duty?",
            listOf("Ksh 160,000", "Ksh 80,000", "Ksh 40,000", "Ksh 640,000"), 0,
            "4% applies in cities, municipalities and gazetted towns: 4% × 4,000,000 = Ksh 160,000. Outside them it's 2%. Duty is on the higher of the price or the government valuation.",
            source = "Stamp Duty Act; Ministry of Lands, 2026", timeSensitive = true),
        quiz("ho-car-cost-month", T, 2, "A car costs Ksh 15,000 fuel, 2,500 parking and 4,000 insurance a month, plus Ksh 3,000 servicing. What's the monthly running cost?",
            listOf("Ksh 24,500", "Ksh 15,000", "Ksh 19,000", "Ksh 21,500"), 0,
            "15,000 + 2,500 + 4,000 + 3,000 = Ksh 24,500, before the value the car loses each year. Compare with matatu and ride-hailing costs before buying.",
            source = "Morph Academy", tryThis = "Add up last month's transport spending in Patterns.", action = Action.PATTERNS),
        concept("ho-depreciation", T, 2, "A Ksh 1.5 million car loses 15% of its value a year. What's it worth after 3 years?",
            "1.5M × 0.85 × 0.85 × 0.85 ≈ Ksh 920,000. You've lost about Ksh 580,000, roughly Ksh 16,000 a month, on top of running costs. Value loss is the biggest hidden car cost.",
            source = "Morph Academy"),
        quiz("ho-rent-rule", T, 2, "Your net pay is Ksh 80,000. A common guide says rent should take at most about a third. What's the max?",
            listOf("About Ksh 26,700", "About Ksh 40,000", "About Ksh 16,000", "About Ksh 53,000"), 0,
            "80,000 ÷ 3 ≈ Ksh 26,700. Above that, saving and emergencies get squeezed. It's a rule of thumb, not a law: lower is better.",
            source = "Morph Academy"),
        concept("ho-agreement", T, 2, "Why have your own lawyer draft or review the sale agreement?",
            "The agreement sets the price, deposit (often 10%), completion date, who pays which costs and what happens if either side backs out. The seller's lawyer acts for the seller. Your own advocate protects you.",
            source = "Law Society of Kenya"),
        quiz("ho-lcb-timing", T, 2, "Within how long of signing must you apply for Land Control Board consent on agricultural land?",
            listOf("6 months", "6 years", "2 weeks", "No deadline"), 0,
            "The Land Control Act requires applying within six months of the agreement, or the deal can become void. The High Court can extend this in some cases.",
            source = "Land Control Act, Cap 302, s. 8"),
        concept("ho-beacons", T, 2, "On a site visit, why look for the beacons?",
            "Beacons are survey markers at the plot's corners. Missing or moved beacons can mean a boundary dispute or the wrong plot being sold. A licensed surveyor can re-establish them against the map.",
            source = "Survey of Kenya"),
        quiz("ho-spousal-consent", T, 2, "Selling or charging a family home often needs whose consent, even if only one spouse is on the title?",
            listOf("The other spouse", "The chief", "The county governor", "The neighbours"), 0,
            "Matrimonial property law and the Land Act protect spouses: lenders and buyers usually ask for spousal consent. Skipping it can make the deal open to challenge.",
            source = "Land Act 2012; Matrimonial Property Act 2013"),
        quiz("ho-gross-yield", T, 2, "A flat costs Ksh 6 million and rents for Ksh 35,000 a month. What's the gross rental yield?",
            listOf("7%", "3.5%", "12%", "0.6%"), 0,
            "Yearly rent 35,000 × 12 = 420,000; ÷ 6,000,000 = 7%. Gross yield ignores tax, empty months, repairs and service charge, so the real return is lower.",
            source = "Morph Academy"),
        concept("ho-chama-land", T, 2, "Many chamas buy land together. What protects each member?",
            "Register the group (or a company) properly, put the title in its name, record each member's share in writing, and agree in the constitution how to exit or subdivide. Verbal promises cause most chama land fights.",
            source = "Morph Academy"),
        quiz("ho-ground-rent", T, 2, "You own leasehold land in a town. What yearly charge might you owe the government on top of county rates?",
            listOf("Ground rent", "Stamp duty", "Capital gains tax", "Excise duty"), 0,
            "Leasehold owners pay annual ground rent (land rent). Unpaid rent and rates can block a future sale until cleared, so ask the seller for clearance certificates.",
            source = "Land Act 2012"),

        // ---------- Level 3: Pro ----------
        quiz("ho-price-to-rent", T, 3, "A house costs Ksh 8 million and similar ones rent for Ksh 40,000 a month. What's the price-to-rent ratio?",
            listOf("About 17", "About 200", "About 5", "About 40"), 0,
            "8,000,000 ÷ (40,000 × 12) ≈ 16.7. The higher the ratio, the more renting tends to win. Above about 20, renting and investing the difference often comes out ahead.",
            source = "Morph Academy"),
        quiz("ho-mortgage-payment", T, 3, "An Ksh 8 million mortgage at 14% over 20 years costs about how much a month?",
            listOf("About Ksh 99,500", "About Ksh 33,000", "About Ksh 56,000", "About Ksh 150,000"), 0,
            "Using the standard loan formula, about Ksh 99,500 a month, versus Ksh 40,000 to rent the same house. Over 20 years you'd pay about Ksh 23.9 million in total.",
            source = "Morph Academy"),
        quiz("ho-mri", T, 3, "A landlord collects Ksh 50,000 a month in residential rent. What's the monthly rental income tax?",
            listOf("Ksh 3,750", "Ksh 5,000", "Ksh 15,000", "Nothing"), 0,
            "Monthly Rental Income tax is 7.5% of gross rent for residential landlords earning Ksh 288,000 to 15 million a year: 7.5% × 50,000 = Ksh 3,750, filed on iTax by the 20th. A 2026 plan to raise it to 10% was dropped.",
            source = "KRA, 2026; Finance Act 2026", timeSensitive = true),
        quiz("ho-net-yield", T, 3, "A Ksh 8M flat rents for Ksh 50k a month. Minus 7.5% rental tax, Ksh 60k service charge, one empty month and Ksh 30k repairs a year, what's the net yield?",
            listOf("About 5.2%", "About 7.5%", "About 3%", "About 9%"), 0,
            "Rent 600k − tax 45k − service 60k − empty month 50k − repairs 30k = 415k. ÷ 8M ≈ 5.2%. Gross yields flatter property; compare the net figure with what other investments pay.",
            source = "KRA, 2026", timeSensitive = true),
        quiz("ho-fraud-red-flags", T, 3, "Which is the biggest red flag when buying land?",
            listOf("Seller wants full cash before any search", "Seller has a lawyer", "Seller shows a recent search", "Price matches the area"), 0,
            "Fraudsters push for quick cash and dodge checks. Other red flags: price far below market, a title in a dead person's name, a seller who won't meet at the registry, or a fresh ID.",
            source = "Ministry of Lands; DCI warnings"),
        concept("ho-mother-title", T, 3, "A company sells you a plot from a \"mother title\" that hasn't been subdivided yet. What's the risk?",
            "You're buying a promise, not a registered plot. If approvals stall, the firm folds or plots are sold twice, you may wait years or lose out. Check approvals, subdivision progress, and pay in stages tied to milestones.",
            source = "Morph Academy"),
        concept("ho-off-plan", T, 3, "What are the main risks of buying an apartment off-plan?",
            "Delays, a stalled project if the developer runs out of cash, a finish worse than the showroom, and a title that takes years. Lower prices pay you for these risks. Check the developer's track record and approvals, and pay into escrow where possible.",
            source = "Morph Academy"),
        quiz("ho-cgt", T, 3, "You sell a plot for Ksh 5 million that you bought for Ksh 2 million. What's the capital gains tax, ignoring costs?",
            listOf("Ksh 450,000", "Ksh 150,000", "Ksh 750,000", "Ksh 300,000"), 0,
            "CGT is 15% of the gain: 15% × (5M − 2M) = Ksh 450,000. Buying and improvement costs can be deducted from the gain, so keep receipts.",
            source = "Finance Act 2022; KRA", timeSensitive = true),
        quiz("ho-kmrc-gap", T, 3, "On a Ksh 4M, 20-year loan, a 9.5% rate costs about Ksh 37,300 a month. About how much does 14% cost?",
            listOf("About Ksh 49,700", "About Ksh 38,000", "About Ksh 60,000", "About Ksh 42,000"), 0,
            "At 14% it's about Ksh 49,700, roughly Ksh 12,400 more a month. Small rate differences become millions over 20 years, so compare lenders and refinance-backed (KMRC) offers.",
            source = "Morph Academy"),
        concept("ho-buy-costs", T, 3, "Apart from the price and stamp duty, what transaction costs should a buyer budget for?",
            "Legal fees (set by the Advocates' Remuneration Order), valuation and survey fees, search and registration fees, and for agricultural land, Land Control Board fees. Together they can add several percent to the price.",
            source = "Law Society of Kenya; Ministry of Lands"),
        quiz("ho-stamp-valuation", T, 3, "You agree to buy a plot for Ksh 3M, but the government valuer puts it at Ksh 3.5M. Rural rate applies. What stamp duty do you pay?",
            listOf("Ksh 70,000", "Ksh 60,000", "Ksh 140,000", "Ksh 120,000"), 0,
            "Duty is charged on the higher of the price or the valuation: 2% × 3,500,000 = Ksh 70,000. Under-declaring the price doesn't help.",
            source = "Stamp Duty Act; Ministry of Lands, 2026", timeSensitive = true),
        concept("ho-rent-invest-diff", T, 3, "\"Rent and invest the difference\": what does it mean?",
            "If owning costs Ksh 99,500 a month and renting costs Ksh 40,000, a renter who invests the Ksh 59,500 gap (and the deposit) can end up wealthier, if they really invest it. Most people don't, which is why forced saving through a mortgage helps some.",
            source = "Morph Academy"),

        // ---------- Level 4: Shark ----------
        concept("ho-kmrc", T, 4, "What is KMRC, and how does it make mortgages cheaper?",
            "The Kenya Mortgage Refinance Company lends long-term, low-cost money to banks and SACCOs, which then offer home loans below about 10% for up to 25 years to qualifying low- and middle-income buyers.",
            source = "KMRC; Business Daily, 2026", timeSensitive = true),
        quiz("ho-mortgage-market", T, 4, "Roughly how many residential mortgage accounts did Kenya have at the end of 2025?",
            listOf("About 31,000", "About 310,000", "About 3 million", "About 3,000"), 0,
            "CBK counted about 30,700 accounts, averaging about Ksh 10 million each, in a country of over 50 million people. Most Kenyans build homes slowly with cash instead.",
            source = "CBK Bank Supervision Report, 2025", timeSensitive = true),
        quiz("ho-mortgage-relief", T, 4, "How much mortgage interest on your own home can you deduct before PAYE each year?",
            listOf("Up to Ksh 360,000", "Up to Ksh 36,000", "Up to Ksh 1 million", "None"), 0,
            "Interest on a loan from a qualifying lender to buy or improve the home you live in is deductible up to Ksh 360,000 a year (Ksh 30,000 a month). At 30% PAYE that's up to Ksh 108,000 a year saved.",
            source = "KRA notice, Tax Laws (Amendment) Act 2024", timeSensitive = true),
        concept("ho-housing-levy", T, 4, "How does the Affordable Housing Levy work?",
            "Employees pay 1.5% of gross pay, matched by the employer, collected by KRA. It funds the Affordable Housing Programme. Since December 2024 it's deducted before PAYE. To apply for a unit, register on Boma Yangu.",
            source = "Affordable Housing Act 2024; KRA", timeSensitive = true,
            tryThis = "Register on Boma Yangu (bomayangu.go.ke) to see your levy and housing options."),
        quiz("ho-boma-yangu", T, 4, "What is Boma Yangu?",
            listOf("The portal to apply for affordable housing units", "A land rates app", "A KMRC mortgage product", "A REIT on the NSE"), 0,
            "Boma Yangu is the government portal (and USSD *832#) where you register, save a deposit and apply for units under the Affordable Housing Programme.",
            source = "State Department for Housing", timeSensitive = true),
        concept("ho-sectional-title", T, 4, "If you buy an apartment, what is a sectional title?",
            "Under the Sectional Properties Act 2020, each unit gets its own title, and owners jointly own common areas (stairs, parking, gardens) through a management corporation. It replaced the old long-lease system for flats.",
            source = "Sectional Properties Act 2020"),
        quiz("ho-service-charge", T, 4, "In an apartment block, what does the service charge usually pay for?",
            listOf("Security, cleaning, lifts, common-area repairs", "Your mortgage interest", "Land rates on your unit", "Stamp duty"), 0,
            "Owners share the cost of running common areas. Check the service charge history and sinking fund before buying. Unpaid charges can be chased, and rising ones eat your yield.",
            source = "Sectional Properties Act 2020"),
        concept("ho-reit", T, 4, "What is a REIT, and why might it beat buying a flat for some people?",
            "A Real Estate Investment Trust pools money to own property. An income REIT (I-REIT) must pay out most of its income. You get property exposure from small amounts, with no tenants to chase, and can sell units on the NSE, though trading can be thin.",
            source = "CMA REIT Regulations"),
        quiz("ho-ireit-vs-dreit", T, 4, "What's the difference between an I-REIT and a D-REIT in Kenya?",
            listOf("I-REITs own rented property; D-REITs build", "D-REITs pay more dividends", "I-REITs are only for foreigners", "No difference"), 0,
            "Income REITs hold finished, rent-earning property and pay regular distributions. Development REITs fund construction and earn when they sell or let, so payouts are lumpier.",
            source = "CMA; NSE"),
        quiz("ho-import-duty", T, 4, "Which taxes are charged on a used car imported into Kenya?",
            listOf("Import duty, excise, VAT, IDF and RDL", "Only VAT", "Only import duty", "Stamp duty and CGT"), 0,
            "KRA charges import duty, excise duty (rising with engine size), 16% VAT and the IDF and RDL levies, on a depreciated retail value. Taxes can roughly match the car's price.",
            source = "KRA; The Star, 2026", timeSensitive = true),
        quiz("ho-8-year-rule", T, 4, "How old can a used car be when imported into Kenya?",
            listOf("Up to 8 years from manufacture", "Up to 15 years", "Any age", "Up to 3 years"), 0,
            "The KEBS standard limits imports to cars under 8 years old from the year of manufacture. Each January the window moves, so check the cut-off year before you buy abroad.",
            source = "KEBS KS 1515; KRA", timeSensitive = true),
        concept("ho-logbook-transfer", T, 4, "Buying a used car: how do you make sure the logbook transfer is safe?",
            "Do an NTSA search on eCitizen to confirm the owner and any loan (a bank may still hold it). The seller starts the transfer online, you accept it, and fees go to NTSA. Don't pay in full until the transfer is in progress.",
            source = "NTSA, 2026", timeSensitive = true, tryThis = "Do an NTSA motor vehicle search before any used-car deal."),
        concept("ho-leverage", T, 4, "Why can a mortgage magnify both gains and losses?",
            "Put 10% down on a Ksh 5M home. If prices rise 10%, your Ksh 500k stake doubles. If they fall 10%, it's wiped out and you still owe the bank. Leverage multiplies outcomes, so keep a cushion for rate rises.",
            source = "Morph Academy"),

        // ---------- Level 5: Legend ----------
        quiz("ho-return-everything", T, 5, "Across 16 rich countries from 1870 to 2015, how did housing returns compare with stocks?",
            listOf("About equal (~7% real) but half as volatile", "Far lower than stocks", "Far higher than stocks", "Housing always lost money"), 0,
            "Jordà and colleagues found real total returns of about 7% a year for both, counting rent. Housing was less volatile. But that counts rent, the larger part of the return. Idle land that earns no rent misses it.",
            source = "Jordà et al., The Rate of Return on Everything, 2019"),
        concept("ho-kiyosaki", T, 5, "Robert Kiyosaki says your home is not an asset. Who's right?",
            "In Rich Dad Poor Dad (1997) an asset puts money in your pocket; a home takes it out. Economists reply that owning saves you rent (\"imputed rent\"), a real return. Both agree a too-big house you can barely afford slows wealth.",
            source = "Kiyosaki, 1997"),
        concept("ho-land-opportunity", T, 5, "A Ksh 2M plot gains 7% a year for 10 years with no income. The same money in a fund earns 10%. Compare.",
            "The plot reaches about Ksh 3.9M; the fund about Ksh 5.2M. Land also has selling costs and is slow to sell. Idle land wins only if it grows faster than alternatives, or if you'll truly build on it.",
            source = "Morph Academy"),
        concept("ho-swynnerton", T, 5, "What was the Swynnerton Plan (1954), and why does it still matter?",
            "A colonial plan to consolidate and register African landholdings with individual titles, to boost cash crops and credit. It built today's title system, but also helped some gain land while detainees and others lost it, seeding lasting disputes.",
            source = "Swynnerton Plan, 1954"),
        concept("ho-constitution-land", T, 5, "How does the 2010 Constitution classify land in Kenya?",
            "Article 61: all land belongs to the people as public, community or private land. Article 65: non-citizens can hold land only on leases of up to 99 years. Article 67 created the National Land Commission to manage public land.",
            source = "Constitution of Kenya 2010, Arts. 61–67"),
        quiz("ho-lra-2012", T, 5, "What did the Land Registration Act 2012 change?",
            listOf("It merged several old registration laws into one", "It abolished title deeds", "It banned leaseholds", "It set stamp duty at 4%"), 0,
            "It replaced older systems (like the Registered Land Act and the Registration of Titles Act) with one law, while the Land Act 2012 covers how land is held, leased and charged.",
            source = "Land Registration Act 2012; Land Act 2012"),
        quiz("ho-title-challenge", T, 5, "Under section 26 of the Land Registration Act, when can a title deed be challenged?",
            listOf("For fraud or illegal, corrupt acquisition", "Never: a title is final", "Only by the President", "Only within 30 days"), 0,
            "A title is conclusive proof of ownership, except where obtained by fraud or misrepresentation to which the owner was party, or illegally, unprocedurally or through a corrupt scheme.",
            source = "Land Registration Act 2012, s. 26"),
        concept("ho-dina", T, 5, "What did Kenya's Supreme Court decide in Dina Management v County Government of Mombasa (2023)?",
            "A title alone isn't enough once its origin is questioned. If the first allocation of public land was illegal, later buyers can't hide behind being innocent purchasers. Lesson: trace the root of title, not just the latest owner.",
            source = "Supreme Court of Kenya, Petition 8 (E010) of 2021, 2023"),
        quiz("ho-ndungu", T, 5, "The 2004 Ndung'u Commission investigated what?",
            listOf("Illegal and irregular allocation of public land", "Mortgage interest rates", "Car import fraud", "Stamp duty evasion"), 0,
            "It found widespread illegal grabbing of public land, often handed to the well-connected, and recommended revoking many titles. It is one reason Dina-style checks matter.",
            source = "Ndung'u Report, 2004"),
        concept("ho-foreign-agri", T, 5, "Can a non-citizen buy agricultural land in Kenya?",
            "Generally no. Land Control Boards must refuse consent for agricultural land sales to non-citizens or to companies not wholly owned by citizens. Diaspora Kenyans who remain citizens can still buy.",
            source = "Land Control Act, Cap 302"),
        quiz("ho-mortgage-npl", T, 5, "What happened to non-performing mortgage accounts in Kenya in 2025?",
            listOf("They roughly doubled to about 8,900", "They fell to zero", "They stayed flat", "They fell by half"), 0,
            "CBK data showed bad mortgage accounts rose from about 4,300 to about 8,900 as rates and job stress bit. Borrowing at the limit leaves no buffer when rates rise.",
            source = "CBK, 2025 Bank Supervision Report", timeSensitive = true),
        you("ho-you-networth-house", T, 5, "Your net worth is {net_worth}. If most of it were one house you live in, what's the catch?",
            "It's concentrated in one illiquid asset that pays no cash. You can't sell a bedroom in an emergency, and it doesn't fund freedom unless you rent it out or sell. Balance property with assets that pay income.",
            tryThis = "List what share of your net worth is property vs cash and investments.", action = Action.ACCOUNTS),
    )
}
